-- function public.post_exp(_user_id bigint, _amount integer, _source_type character varying, _source_id bigint, _rule_key character varying, _idempotency_key character varying, _actor_id bigint, _reason text, _metadata jsonb)
-- Generated by db/tools/export-schema.mjs from the live database. Do not edit by hand:
-- change the database through a migration in db/migrations, then re-run the exporter.

CREATE OR REPLACE FUNCTION public.post_exp(_user_id bigint, _amount integer, _source_type character varying, _source_id bigint, _rule_key character varying DEFAULT NULL::character varying, _idempotency_key character varying DEFAULT NULL::character varying, _actor_id bigint DEFAULT NULL::bigint, _reason text DEFAULT NULL::text, _metadata jsonb DEFAULT NULL::jsonb)
 RETURNS TABLE(created boolean, awarded integer, exp_after bigint, previous_level integer, new_level integer)
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_exp bigint;
    v_level int;
    v_new bigint;
    v_new_level int;
BEGIN
    IF _amount IS NULL OR _amount = 0 THEN
        RAISE EXCEPTION USING ERRCODE = 'CD400', MESSAGE = 'EXP amount must not be zero';
    END IF;
    IF _amount < 0 AND _source_type <> 'adjustment' THEN
        RAISE EXCEPTION USING ERRCODE = 'CD400', MESSAGE = 'Only adjustments can remove EXP';
    END IF;

    SELECT i.exp, i.exp_level INTO v_exp, v_level
    FROM profile.info i
    WHERE i.user_id = _user_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'CD404', MESSAGE = 'User profile not found';
    END IF;

    IF EXISTS (
        SELECT 1 FROM profile.exp_transaction t
        WHERE t.user_id = _user_id
          AND (
                (_idempotency_key IS NOT NULL AND t.idempotency_key = _idempotency_key)
             OR (_source_id IS NOT NULL AND t.source_type = _source_type AND t.source_id = _source_id)
          )
    ) THEN
        RETURN QUERY SELECT false, 0, v_exp, v_level, v_level;
        RETURN;
    END IF;

    v_new := GREATEST(v_exp + _amount, 0);
    IF v_new = v_exp THEN
        RETURN QUERY SELECT false, 0, v_exp, v_level, v_level;
        RETURN;
    END IF;

    v_new_level := public.level_for_exp(v_new);

    INSERT INTO profile.exp_transaction
        (user_id, amount, source_type, source_id, rule_key, exp_after, idempotency_key, actor_id, reason, metadata)
    VALUES
        (_user_id, (v_new - v_exp)::int, _source_type, _source_id, _rule_key, v_new, _idempotency_key, _actor_id, _reason, _metadata);

    UPDATE profile.info SET exp = v_new, exp_level = v_new_level, updated_at = now() WHERE user_id = _user_id;

    RETURN QUERY SELECT true, (v_new - v_exp)::int, v_new, v_level, v_new_level;
END;
$function$;
